from mcp.server import MCPServer
mcp = MCPServer("MCP Academy BIM")

@mcp.tool()
def get_course_model_counts(category: str) -> dict:
    """Read the STATIC IFC course snapshot; does not query Revit."""
    counts = {"IfcWall":30,"IfcDoor":15,"IfcWindow":7,"IfcSlab":11}
    if category not in counts:
        return {"error": "unsupported_category", "category": category}
    return {"category":category,"count":counts[category],"source":"IFC snapshot"}

if __name__ == "__main__":
    mcp.run(transport="stdio")
